content:
在 Carbon Typst Blog 中，除了博客文章页面之外，还有一些其他类型的页面，例如分类页、标签页、归档页等。这些页面的模板和样式与博客文章页面是分开的，因此你可以通过调整这些页面的模板来定制它们的外观和功能。这些页面对应的 `index.typ` 文件可以参考 介绍。

和博客文章不同，这些页面在构建时需要接受命令行参数的控制，从而让构建脚本可以正确渲染这些界面。Carbon Typst Blog 提供了一套查询输入的工具函数，帮助你从命令行参数中获取相关信息，例如当前页面的标签、分类、页码等。这些工具函数定义在 `lib/typ2html/sys-input.typ` 文件中，你可以在这些函数的基础上进行调整和扩展，以满足你的需求。

以下是所有可用的查询输入工具函数：
基础函数
- `query-input(key, default: none)` : 获取指定键的命令行参数值，如果没有提供则返回默认值。
- `query-posts()` : 获取博客文章数据的 JSON 对象，其中包含了所有博客文章的相关信息，*按照时间升序排序*，格式如下：
 ```json
 [
 {
 "slug": "introduction",
 "url": "/posts/introduction/",
 "title": "Carbon Typst Blog 介绍",
 "description": "本文主要介绍 Carbon Typst Blog 的基本功能和配置方式。",
 "tags": ["博客搭建"],
 "category": "",
 "date": "2026-03-17"
 },

 ```
- `query-slugs()` : 获取标签和分类的 slug 数据的 JSON 对象，其中包含了标签和分类名称与 slug 的映射关系，格式如下：
 ```json
 {
 "tags": {
 "博客搭建": "博客搭建",
 "配置指南": "配置指南",
 "写作指南": "写作指南",
 "Typst": "typst"
 }, "categories": {
 "测试": "测试"
 }
 }
 ```
标签和分类相关函数

- `query-route-tag(default: "")` : 获取当前页面的标签 slug，在标签页中使用。
- `query-route-category(default: "")` : 获取当前页面的分类 slug，在分类页中使用。
- `query-tag-slug-of(value)` : 获取指定标签的 slug。
- `query-category-slug-of(value)` : 获取指定分类的 slug。
分页相关函数

- `query-route-page(default: 1)` : 获取当前页面的页码，默认为 1。
- `query-route-page-size(default: 10)` : 获取当前页面的每页显示数量，默认为 10。
- `query-page-bounds(total, page: 1, page-size: 10)` : 根据总条目数、当前页码和每页显示数量计算分页信息，返回一个包含当前页码、每页显示数量、总页数、起始索引和结束索引的对象。

使用上述函数，你就可以在分类页、标签页等页面中获取到当前页面的标签或分类信息，以及分页信息，从而根据这些信息来渲染页面内容。以下是标签页 `pages/tags/[tag]/index.typ` 的示例代码：

```typ
#import "../../../config.typ": *
// 获取博客文章数据和当前页面的标签信息 
#let posts = query-posts()
#let current = query-route-tag()
#let route-page = query-route-page()
#let route-page-size = query-route-page-size(default: 10)

// 设置页面标题和描述
#show: template-page.with(
 title: if current == "" { "标签详情" } else { "标签：" + current },
 description: "标签详情页面",
)

// 渲染页面的面包屑导航
#render-page-breadcrumb(
 items: (("/", "首页"), ("/tags/", "标签")),
)

// 展示当前标签
#current

// 根据当前标签过滤博客文章
#let matched = posts.filter(post => post.tags.any(tag => tag == current))

// 根据过滤后的文章数量和分页信息计算分页边界
#let bounds = query-page-bounds(matched.len(), page: route-page, page-size: route-page-size)
#let current-page = int(bounds.at("page", default: 1))
#let total-pages = int(bounds.at("total-pages", default: 1))
#let start-index = int(bounds.at("start-index", default: 0))
#let end-index = int(bounds.at("end-index", default: -1))

// 渲染文章列表
#if matched.len() == 0 {
 html.div(class: "error-block", {
 "暂无文章"
 })
} else {
 html.div(class: "posts-grid", {
 for i in range(end-index, start-index - 1, step: -1) {
 let post = matched.at(i)
 let date-parts = post.date.split("-")
 let post-date-text = if date-parts.len() == 3 {
 format-post-date(datetime(
 year: int(date-parts.at(0)),
 month: int(date-parts.at(1)),
 day: int(date-parts.at(2)),
 ))
 } else {
 post.date
 }
 html.elem("div", attrs: (
 class: "post-card",
 "data-post-url": post.url,
 ), {
 html.div(class: "post-title", {
 html.a(class: "post-card-link", href: post.url, post.title)
 })
 html.div(class: "post-description", {
 post.description
 })
 if post.tags.len() != 0 {
 html.div(class: "post-card-tags", {
 for tag in post.tags {
 render-tag-link(tag, href: "/tags/" + query-tag-slug-of(tag) + "/")
 }
 })
 }
 html.div(class: "post-date", {
 post-date-text
 })
 })
 }
 })

 render-pagination-nav(
 "/tags/" + query-tag-slug-of(current) + "/",
 current-page,
 total-pages,
 aria-label: "标签分页",
 )
}
```

如果你需要深度修改这些页面的结构和样式，可以直接编辑对应的 `index.typ` 文件，并使用上述查询输入工具函数来获取必要的数据和信息。通过这种方式，你可以灵活地定制分类页、标签页等页面的内容和布局，以满足你的需求。

本文主要介绍 `config.typ` 和 `site.config.json` 这两个配置文件的作用和使用方法，以及如何通过它们来定制 Carbon Typst Blog 的外观和功能。
`config.typ`

`config.typ` 是 Carbon Typst Blog 的主要配置文件，位于项目的根目录下。它是一个 Typst 文件，定义了博客的全局设置、模板和一些辅助函数。通过修改 `config.typ`，你可以定制博客的标题、导航链接、标签样式、页脚内容等。

以下是可能的 `config.typ` 文件内容：

```typ
// 引入 typ2html 库，提供 HTML 导出相关的功能和模板
#import "lib/typ2html/typ2html.typ" : *

// 定义页脚内容，可以在这里添加版权信息、联系方式等
#let footer-content = [
 2026 \~ Present Carbon Typst Blog

// 定义标签的样式和图标，可以根据需要添加更多的标签选项
#let tag-options = (
 "博客搭建": (preset: "cyan", "icon": "/assets/icons/rocket.svg"),
 "Typst": ("preset": "teal", "icon": "/assets/icons/pen.svg"),
 "写作指南": ("preset": "blue", "icon": "/assets/icons/edit.svg"),
 "配置指南": ("preset": "green", "icon": "/assets/icons/settings.svg"),
)

// 将标签选项应用到标签链接和标签卡片的渲染函数中，使其在博客中生效
// 这一部分无需修改，除非你需要自定义标签的渲染方式
#let render-tag-link = render-tag-link.with(tag-options: tag-options)
#let render-tag-card = render-tag-card.with(tag-options: tag-options)

// 定义博客的模板，包括站点标题、导航链接、语言、页脚内容等
#let templates = make-templates(
 // 站点标题，将显示在浏览器标签页和博客的头部
 site-title: "Carbon Typst Blog",
 // 导航链接，定义博客的主导航菜单，可以根据需要添加或修改链接
 header-links: (
 "/": "首页",
 "/categories/": "分类",
 "/tags/": "标签",
 "/archive/": "归档",
 "/about/": "关于",
 ),
 // 博客的语言设置，影响文本的排版和一些默认的文本内容
 lang: "zh",
 // 页脚内容，将显示在博客的底部，可以使用 HTML 或 Typst 的文本格式化功能
 footer-content: footer-content,
 // 标签选项，将在博客中使用定义的标签样式和图标
 tag-options: tag-options,
 // 自定义 CSS 文件，可以在这里添加你自己的样式来定制博客的外观
 custom-css: (
 "/assets/custom.css",
 ),
 // 自定义 JavaScript 文件，可以在这里添加你自己的脚本来增强博客的功能
 custom-script: (

 )
)

// 从模板中提取出文章模板和页面模板，供博客文章和页面使用
#let template-page = templates.page
#let template-post(..args) = {
 // 你可以在这里自定义 PDF 预览的效果
 // 以下是一些示例设置，你可以根据需要进行调整
 set page(height: auto, width: 30cm)
 set text(16pt, font: ("IBM Plex Sans SC"), lang: "zh")
 show raw: text.with(font: ("Zed Plex Mono", "IBM Plex Sans SC"))
 show math.equation: set text(16pt)
 set table(inset: 8pt)
 set grid(inset: 8pt)

 (templates.post)(..args)
}

```

其中，标签支持的颜色预设为：`gray`，`cool-gray`，`warm-gray`，`red`，`magenta`，`purple`，`blue`，`cyan`，`teal` 和 `green`。标签的图标应该是一个 SVG 图像的 URL 地址，你可以使用博客中提供的图标，也可以使用你自己的图标。你可以在 这个图标库 中下载到符合 Carbon Design System 设计规范的 SVG 图标，或者使用其他来源的图标，只要它们是 SVG 格式的即可。你可以在定义标签选项时使用这些预设颜色，或者在 `lib/typ2html/tag.typ` 中自定义颜色信息。
`site.config.json`

`site.config.json` 是一个可选的 JSON 配置文件，位于项目的根目录下。它主要用于存储一些需要在博客运行时访问的配置信息。目前 `site.config.json` 中的配置项包括：

```json
{
 "siteTitle": "Carbon Typst Blog",
 "siteUrl": "https://example.com",
 "author": "Carbon Typst Blog",
 "description": "Carbon Typst Blog RSS Feed",
 "language": "zh-cn"
}
```

其中，`siteTitle` 是博客的标题，`siteUrl` 是博客的 URL 地址，`author` 是博客的作者名称，`description` 是博客的描述信息，`language` 是博客的语言设置。你可以根据需要修改这些配置项来定制你的博客。需要注意的是，`site.config.json` 中的配置项会在博客运行时被读取并且在生成 RSS Feed 和其他需要使用这些信息的地方生效，因此请确保这些信息的准确性和完整性。

首先写这个网站的起因是邮箱发作业实在是过于麻烦，看着隔壁广州计算机的都用着 Matrix（一个我们大学学生运维的 OJ ，即在线判题平台），一点提交就有结果，而我们交作业却是原始的上交源文件和运行截图，我也无何办法，谁让我们是材料计算机呢（并无歧视材料的意思，只是单纯地憎恶化学，高中本就没选）。等我和课代表商量的时候，他也表示早已被不按规则提交的作业搞得苦不堪言（乐），想了想，虽然费劲写个小破站有些浪费时间，与大卷之势相悖，但毕竟也算有点意思，便做了下去。
开始

最初的文件是直接抄中国人民公安大学的一道信安题的，代码附上：

```php
header("Content-type: text/html;charset=utf-8");
error_reporting(0);
//设置上传目录
define("UPLOAD_PATH", dirname(__FILE__) . "/upload/");
// define("UPLOAD_URL_PATH", str_replace($_SERVER['DOCUMENT_ROOT'], "", UPLOAD_PATH));
if (!file_exists(UPLOAD_PATH)) {
 mkdir(UPLOAD_PATH, 0755);
}
if (!empty($_POST['submit'])) {
 if (!$_FILES['file']['size']) {
 echo "<script>alert('请添加上传文件')</script>";
 } else {
 $name = basename($_FILES['file']['name']);
 if (move_uploaded_file($_FILES['file']['tmp_name'], UPLOAD_PATH . $name)) {
 echo "<script>alert('上传成功')</script>";
 echo "上传文件相对路径<br>" . "/upload/" . $name;
 } else {
 echo "<script>alert('上传失败')</script>";
 }
 }
}
$myfile = fopen("log.txt", "a") or die("Unable to open file!");
 fwrite($myfile,$_SERVER["REMOTE_ADDR"]);
 $txt="\n";
 fwrite($myfile,$txt);
 fclose($myfile);
?>
<!DOCTYPE html>
<html>
<head>
 <meta charset="UTF-8">
 <title>PPSUC 文件上传 - js前端验证</title>
</head>
<body>
 <h1>PPSUC 文件上传 - js前端验证</h1>
 <p>本题从PPSUC窃取得来</p>
 <form action="" method="post" enctype="multipart/form-data" onsubmit="return checkfilesuffix()">
 <label for="file">Filename:</label>
 <input type="file" name="file" id="file" />
 <br />
 <input type="submit" name="submit" value="Submit" />
 </form>
<script>
function checkfilesuffix()
{
 var file=document.getElementsByName('file')[0]['value'];
 if(file==""||file==null)
 {
 alert("请添加上传文件");
 return false;
 }
 else
 {
 var whitelist=new Array(".jpg",".png",".gif");
 var file_suffix=file.substring(file.lastIndexOf("."));
 if(whitelist.indexOf(file_suffix) == -1)
 {
 alert(":(该文件不允许上传:(");
 return false;
 }
 }
}
</script>
</body>
</html>
```

这题考的是 JS 前端验证的绕过，解出题后的我深知前端验证的不可靠，便知道敏感的操作限制应该加在后端了。但毕竟前端也得有点拦一下不是，否则累死后端不说，代码冗杂也是一个问题。上百度抄一抄，后端的后缀限制也完成了（解释一下，之所以限制文件后缀，一方面是因为提交的文件格式问题，一方面是安全问题，假若给你上传了一个 php 木马而我又没加限制访问的情况下， RCE 就是件很简单的事情了，之后你可以查看和操作任意权限允许的文件，总之是很危险的事）。
在完成后缀的限制后，我又加了如下的诸多验证：

*文件大小非空且大小须小于512KB(后来改成了666KB)* ：否则给你当网盘使那我服务器也是难顶，而且源文件最大也没什么可能超过 10 KB，截图预计也是几十 KB
*upload目录的访问限制*：可不能给随便偷了作业看
*姓名不能为空且不多于4个字*：这个问过课代表，我们班的名字没有超过 3 个字的
*学号范围*：086-199 ，但有一个人的学号孤悬在外，有些奇怪（乐）
*姓名和学号的联合验证*：这个是前两天才加上去的，主要是忘了之前的军事课有份名单（但是那位竟然是没有的，再处理吧）
后端处理逻辑重构

一开始我是设置先新建（姓名+学号）的一个目录，再逐个文件进行判断，若符合条件则放进目录里，但这就会引发一个问题，如果有文件不符合条件的话目录仍会存在，而为了防止有意或是无意的重复上传导致原文件被覆盖，我又设置了若目录已存在则不能继续放文件,于是我在上机课的时候改成了先全部验证通过再上传目录。
管理员端

毕竟作业也不是我收的，如果每次都要我来登录服务器下载未免也太过麻烦，于是我抄了段多级目录压缩的代码，在管理员通过验证后将提交上的作业打包成了个 zip ，再存储于基于 SHA256 算法生成的时间哈希值命名的目录中，这样大概便无法被直接扫描出来了。
管理员的登录验证我采用的是RSA公钥加密出的一段 base64 编码的字符串，若在后端用私钥解密后得到明文"admin"便通过验证，但想了想似乎没必要用非对称加密，有空再改。
除此之外，我还加了个验证码，但是在 Firefox 上似乎不能正常刷新，于是就没加在学生端了。
前端的样式

这个是我最无奈的地方，个人的美术功底着实是捞得亚匹，布局和配色搞得乱七八糟，在此就希望同学多多与我反馈了。
一些问题
开源

本来打算上传到 github 的，但是还没处理好重要文件的放置（总不能学号和姓名也开源不是）。

