 nm ^= mzd_read_bit(tker, ri, mi++) & (x >> i) & (x >> j) & 1;
 //assert(mi == n_cols);
 assert(nm == 0);
 }
 }
 */
 for(size_t ri = 0; ri < tker->nrows; ri++)
 {
 printf("%d ", (int)tgt);
 for(size_t ci = 0; ci < tker->ncols; ci++)
 printf("%d", (int)mzd_read_bit(tker, ri, ci));
 printf("\n");
 }
 mzd_free(tker);
}
int main()
{
 for(size_t i = 0; i < 256; i++)
 process(i);
}
```

