constexpr size_t N_MONO = 1 + 256 + 256 * 255 / 2;
using deg2_rel = std::bitset<1 + 256 + 256 * 255 / 2>;
using deg2_rel64 = std::bitset<1 + 64 + 64 * 63 / 2>;
using lin_rel = std::bitset<256>;
struct sym_u64
{
 lin_rel st[64] {};
 sym_u64& operator^=(const sym_u64& rhs)
 {
 for(size_t i = 0; i < 64; i++)
 st[i] ^= rhs.st[i];
 return *this;
 }
 sym_u64 operator^(const sym_u64& rhs) const
 {
 sym_u64 ret = *this;
 ret ^= rhs;
 return ret;
 }
 sym_u64 operator<<(int by) const
 {
 sym_u64 ret {};
 for(size_t i = 0; i < 64 - by; i++)
 ret.st[i + by] = st[i];
 return ret;
 }
 sym_u64 operator>>(int by) const
 {
 sym_u64 ret {};
 for(size_t i = 0; i < 64 - by; i++)
 ret.st[i] = st[i + by];
 return ret;
 }
 sym_u64 rotl(int by) const
 {
 sym_u64 ret {};
 for(size_t i = 0; i < 64; i++)
 ret.st[(i + by)%64] = st[i];
 return ret;
 }
};
struct sym_xs256
{
 sym_u64 s0, s1, s2, s3;
 sym_xs256()
 {
 for(size_t i = 0; i < 64; i++)
 {
 s0.st[i][i] = true;
 s1.st[i][i+64] = true;
 s2.st[i][i+128] = true;
 s3.st[i][i+192] = true;
 }
 }
